import java.util.Scanner;

public class Main {

    public static String funkyNumbers(String nStr) {
        int n = Integer.parseInt(nStr);
        String funkyNumber = "NO";

        int maxTriangle = maxTrianglePossible(n);

        for (int i = maxTriangle; i > 0; i--) {
            int firstTriangle = triangleNumbers(i);
            int rem = n - firstTriangle;

            if (rem == 0) continue;

            int secFactor = maxTrianglePossible(rem);
            int secTriangle = triangleNumbers(secFactor);

            int triangles = firstTriangle + secTriangle;

            if (triangles == n) {
                funkyNumber = "YES";
                break;
            }
        }

        return funkyNumber;
    }

    public static int maxTrianglePossible(int n) {
        // k(k+1) / 2 = n where n is an integer
        // k(k+1) = n*2
        // k^2 + k - n*2 = 0 -> factors

        int k = (int) Math.floor(Math.sqrt(n * 2));

        return k;
    }

    public static int triangleNumbers(int x) {
        int f = (x * (x + 1)) / 2;

        return f;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNextLine()) {
            String input = scanner.nextLine().trim();
            String res = funkyNumbers(input);
            System.out.println(res);
        }
        scanner.close();
    }
}

